ma5:=ma(c,5);
ma10:=ma(c,10);
ma30:=ma(c,30);
波动:=(c-llv(l,1)+h-o)/(hhv(h,55)-llv(l,55))*100;
实体比例:=(c-o)/(h-l+0.001)*100;
30均线涨:=ma30>ref(ma30,1) and ref(ma30,1)>ref(ma30,2) and ref(ma30,2)>ref(ma30,3);
均量涨:=ma(v,20)>ma(v,250) and amount/ma(amount,15)<1.1;
con1:=ma5>ma10 and ma10>=ma30 and ma5>ma30;
con2:=barslast(cross(ma5,ma10));
con3:=barslast(cross(ma5,ma30));
con4:=barslast(cross(ma10,ma30));
tj1:=con1 and con2>con3 and con3>con4 and con2<con4+20 and con2<con3+15;
tj2:=cross(ma10,ma30);
触发:=tj1 and tj2;
触发后周期数:=barslast(触发);
lc:=llv(c,触发后周期数);
rc:=ref(c,触发后周期数);
触发后跌幅:=(1-lc/rc)*100;
con5:=count(cross(ma30,ma5),触发后周期数);
con6:=count(cross(ma30,ma10),触发后周期数);
触发后:=con5=0 and con6=0 and barslast(触发)>0;
回踩:=(l<=ma30 or ref(c,1)<ref(ma30,1)) and c>ma30 and 触发后;
回踩后周期数:=barslast(回踩);
本次踩后周期:=min(回踩后周期数,触发后周期数);
触发下穿:=count(cross(ma10,ma5),触发后周期数);
触发上穿:=count(cross(ma5,ma10),触发后周期数);
踩后下穿:=count(cross(ma10,ma5),本次踩后周期);
死叉根数:=barslast(cross(ma10,ma5));
金叉根数:=barslast(cross(ma5,ma10));
死叉周期:=IF(死叉根数<金叉根数,死叉根数,0);
均线连跌:=ref(ma10,1)<ref(ma10,2) and ref(ma5,1)<ref(ma5,2) and ref(ma10,2)<ref(ma10,3) and ref(ma5,2)<ref(ma5,3);
涨幅分叉:=((c/o>=1.015 and l<ma(c,30) and (ref(ma30,1)>=ref(ma30,2) or (c>ma5 and c>ma10 and o<ma5 and o<ma10))) or  (c/ref(c,1)>=1.04));
黄金回踩:回踩 and 波动>32 and c>o and 实体比例>=15 and 触发后跌幅<20 and ref(死叉周期,1)<10 and 30均线涨>0;

A:=MA(-100*(HHV(HIGH,34)-CLOSE)/(HHV(HIGH,34)-LLV(LOW,34)),19);
B:=-100*(HHV(HIGH,14)-CLOSE)/(HHV(HIGH,14)-LLV(LOW,14));
d:=EMA(-100*(HHV(HIGH,34)-CLOSE)/(HHV(HIGH,34)-LLV(LOW,34)),4);
长期线:=A+100;
短期线:=B+100;
中期线:=d+100;
趋势顶底:(长期线<12 and 中期线<8 and (短期线<7.2 or ref(短期线,1)<5) and (中期线>ref(中期线,1) or 短期线>ref(短期线,1)))
or (长期线<8 and 中期线<7 and 短期线<15 and 短期线>ref(短期线,1)) or (长期线<10 and 中期线<7 and 短期线<1);

con1:=(1-c/ref(c,55))*100>27;
con2:=l=llv(l,34);
con3:=(c/l-1)*100>=1;
冰谷火焰:con1 and con2 and con3;

A:=MA(-100*(HHV(HIGH,34)-CLOSE)/(HHV(HIGH,34)-LLV(LOW,34)),19);
B:=-100*(HHV(HIGH,14)-CLOSE)/(HHV(HIGH,14)-LLV(LOW,14));
d:=EMA(-100*(HHV(HIGH,34)-CLOSE)/(HHV(HIGH,34)-LLV(LOW,34)),4);
长期线:=A+100;
短期线:=B+100;
中期线:=d+100;
底:=(长期线<12 and 中期线<8 and (短期线<7.2 or ref(短期线,1)<5) and (中期线>ref(中期线,1) or 短期线>ref(短期线,1)))
or (长期线<8 and 中期线<7 and 短期线<15 and 短期线>ref(短期线,1)) or (长期线<10 and 中期线<7 and 短期线<1);
趋势顶底离开底部:ref(底,1)=1 and 底=0;

a:=L2_AMO(0);
b:=ma(a,20);
主力资金:a>b and b>0 and b>ref(b,1);

N:=120; 

杯底价:=LLV(L,N);
杯底位置:=BARSLAST(L=杯底价);
左侧高点:=HHV(H,杯底位置);
右侧高点:=HHV(H,杯底位置); 
右侧位置:=BARSLAST(H=右侧高点);
柄部低点:=LLV(L,右侧位置);

杯深:=(左侧高点-杯底价)/左侧高点;
CON1:=杯深>0.1 AND 杯深<0.5;

CON2:=右侧高点>=0.85*左侧高点;

CON3:=(右侧高点-柄部低点)/右侧高点<0.2 AND 柄部低点>杯底价;

CON4:=右侧位置>=3;

突破信号:=CROSS(C,右侧高点) AND V>=REF(V,1)*1.5;

con5:=ref(c,30)<ref(ma(c,250),30);

选股:CON1 AND CON2 AND CON3 AND CON4 AND 突破信号;

LEFTPEAK:=REF(HHV(HIGH,10),61);
RIGHTPEAK:=REF(HHV(HIGH,10),11);
RIM:=(LEFTPEAK+RIGHTPEAK)/2;
CUPLOW:=REF(LLV(LOW,60),11);
CUPHEIGHT:=RIM-CUPLOW;
CUPDEPTH:=1-CUPLOW/RIM;

MIDLOW:=REF(LLV(LOW,20),31);
LEFTMEAN:=REF(MA(CLOSE,20),51);
MIDMEAN:=REF(MA(CLOSE,20),31);
RIGHTMEAN:=REF(MA(CLOSE,20),11);

HANDLELOW:=REF(LLV(LOW,10),1);
HANDLEHIGH:=REF(HHV(HIGH,10),1);
HANDLEDEPTH:=1-HANDLELOW/RIGHTPEAK;
HANDLERETRACE:=(RIGHTPEAK-HANDLELOW)/CUPHEIGHT;
HANDLEVOL:=REF(MA(VOL,10),1)/REF(MA(VOL,20),11);

BREAKVOL:=VOL/REF(MA(VOL,20),1);
PIVOT:=MAX(MAX(LEFTPEAK,RIGHTPEAK),HANDLEHIGH);
PRETREND:=REF(CLOSE,71)/REF(CLOSE,111)-1;

TRENDOK:=PRETREND>=0.20;
CUPSIZEOK:=CUPDEPTH>=0.12 AND CUPDEPTH<=0.33;
RIMOK:=ABS(RIGHTPEAK/LEFTPEAK-1)<=0.05 AND REF(CLOSE,11)>=RIGHTPEAK*0.97;

BOTTOMCENTER:=MIDLOW<=CUPLOW;
BOTTOM_PROXIMITY:=(MIDMEAN-CUPLOW)/CUPHEIGHT;
CUPPROFILEOK:=BOTTOMCENTER AND BOTTOM_PROXIMITY<=0.20 AND LEFTMEAN>=MIDMEAN+CUPHEIGHT*0.15 AND RIGHTMEAN>=MIDMEAN+CUPHEIGHT*0.15;

HANDLESHAPE:=REF(MA(CLOSE,5),1)<=REF(MA(CLOSE,5),6)*1.02;
HANDLEOK:=HANDLEDEPTH>=0.01 AND HANDLEDEPTH<=0.12 AND HANDLERETRACE<=0.40 AND HANDLELOW>=CUPLOW+CUPHEIGHT*0.50 AND HANDLEHIGH<=RIGHTPEAK*1.02 AND HANDLESHAPE;
VOLUMEOK:=HANDLEVOL<=0.80;

SETUP_RAW:=TRENDOK AND CUPSIZEOK AND RIMOK AND CUPPROFILEOK AND HANDLEOK AND VOLUMEOK;

NEWSETUP:=SETUP_RAW AND SUM(REF(IF(SETUP_RAW,1,0),1),20)=0;
AGE:=BARSLAST(NEWSETUP);
K:=MIN(AGE,20);
HASSETUP:=SUM(IF(NEWSETUP,1,0),21)>0;

FIXPIVOT:=REF(PIVOT,K);
FIXLOW:=REF(HANDLELOW,K);

ALIVE:=HASSETUP AND LLV(CLOSE,K+1)>=FIXLOW;
CONFIRM:=ALIVE AND CLOSE>FIXPIVOT*1.005 AND BREAKVOL>=1.50;
UNUSED:=AGE=0 OR SUM(REF(IF(CONFIRM,1,0),1),MAX(K,1))=0;

READY:=ALIVE AND UNUSED;
BRK:=READY AND CONFIRM;
ENTRY:=BRK AND CLOSE<=FIXPIVOT*1.05;

CWH_BREAK_WAIT20_F1:IF(BRK,1,0);

AP:=HHV(H,120);
AT:=HHVBARS(H,120);
BP:=LLV(L,AT+1);
BT:=LLVBARS(L,AT+1);
CP:=HHV(H,BT+1);
CT:=HHVBARS(H,BT+1);
HN:=MAX(CT,1);
DP:=LLV(L,HN);
HC:=LLV(C,HN);
CUPLEN:=AT-CT+1;
PRETREND:=REF(C,AT)/REF(C,AT+40)-1;
RECOVERY:=(CP-BP)/(AP-BP);
ORDEROK:=AT>BT AND BT>CT;
TRENDOK:=PRETREND>=0.10;
CUPOK:=CUPLEN>=30 AND BP/AP>=0.60 AND BP/AP<=0.90;
RECOVEROK:=RECOVERY>=0.75;
TIMEOK:=CT>=4 AND CT<=20 AND CT<=CUPLEN/2;
HANDLEOK:=DP/CP>=0.85 AND HC>=(AP+BP)/2;
PAUSEOK:=COUNT(H<REF(H,1),HN)>=2;
SETUP:=ORDEROK AND TRENDOK AND CUPOK AND RECOVEROK AND TIMEOK AND HANDLEOK AND PAUSEOK;
CCC:IF(REF(C,160)>0,IF(REF(SETUP,1) AND C>REF(CP,1),1,0),REF(C,160));

AP:=HHV(H,120);
AT:=HHVBARS(H,120);
BP:=LLV(L,AT+1);
BT:=LLVBARS(L,AT+1);
CP:=HHV(H,BT+1);
CT:=HHVBARS(H,BT+1);
HN:=MAX(CT,1);
DP:=LLV(L,HN);
HC:=LLV(C,HN);
CUPLEN:=AT-CT+1;
PRETREND:=REF(C,AT)/REF(C,AT+40)-1;
RECOVERY:=(CP-BP)/(AP-BP);
ORDEROK:=AT>BT AND BT>CT;
TRENDOK:=PRETREND>=0.10;
CUPOK:=CUPLEN>=30 AND BP/AP>=0.60 AND BP/AP<=0.90;
RECOVEROK:=RECOVERY>=0.75;
TIMEOK:=CT>=4 AND CT<=20 AND CT<=CUPLEN/2;
HANDLEOK:=DP/CP>=0.90 AND HC>=(AP+BP)/2 AND CP-DP<=(CP-BP)*0.382;
PAUSEOK:=COUNT(H<REF(H,1),HN)>=2;
SETUP:=ORDEROK AND TRENDOK AND CUPOK AND RECOVEROK AND TIMEOK AND HANDLEOK AND PAUSEOK;
BMA250:=REF(MA(C,250),BT);
BHISTORY:=REF(C,BT+249);
BLOWYEAR:=BP<BMA250;
CCCMA250:IF(REF(BHISTORY,1)>0,IF(REF(C,160)>0,IF(REF(SETUP,1) AND C>REF(CP,1) AND C<=REF(CP,1)*1.05 AND C<=MA(C,60)*1.20 AND REF(BLOWYEAR,1),1,0),REF(C,160)),REF(BHISTORY,1));
